public class RISCVAddressAnalyzer : ConstantPropagationAnalyzer {

	public static readonly string RISCV___GLOBAL_POINTER = "__global_pointer$";

	private Address gp_assumption_value;

	private static readonly string REGISTER_GP = "gp";
	private Register gp;

	private static readonly string PROCESSOR_NAME = "RISCV";

	public RISCVAddressAnalyzer() : base(PROCESSOR_NAME)
    {
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		bool canAnalyze = program.getLanguage()
				.getProcessor()
				.equals(Processor.findOrPossiblyCreateProcessor(PROCESSOR_NAME));

		if (!canAnalyze) {
			return false;
		}

		gp = program.getRegister(REGISTER_GP);

		return true;
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		gp_assumption_value = null;

		// check for the __global_pointer$ symbol to see what the global gp
		// value should be
		checkForGlobalGP(program, set, monitor);

		return base.added(program, set, monitor, log);
	}

	/* @Override */
	public AddressSetView flowConstants(Program program, Address flowStart,
			AddressSetView flowSet, SymbolicPropogator symEval, TaskMonitor monitor)
    {

		// get the function body
		Function func = program.getFunctionManager().getFunctionContaining(flowStart);

		if (func != null && gp_assumption_value != null) {
			ProgramContext programContext = program.getProgramContext();
			RegisterValue gpVal = programContext.getRegisterValue(gp, flowStart);
			if (gpVal == null || !gpVal.hasValue()) {
				gpVal = new RegisterValue(gp, BigInteger.valueOf(gp_assumption_value.getOffset()));
				try {
					program.getProgramContext()
							.setRegisterValue(func.getEntryPoint(), func.getEntryPoint(), gpVal);
				}
				catch (ContextChangeException e) {
					// only happens for context register
					throw new AssertException("unexpected", e);
				}
			}
		}

		// follow all flows building up context
		ConstantPropagationContextEvaluator eval =
			new _Anon_ConstantPropagationContextEvaluator_1(monitor, trustWriteMemOption);
			
		eval.setTrustWritableMemory(trustWriteMemOption)
		    .setMinSpeculativeOffset(minSpeculativeRefAddress)
		    .setMaxSpeculativeOffset(maxSpeculativeRefAddress)
		    .setMinStoreLoadOffset(minStoreLoadRefAddress)
		    .setCreateComplexDataFromPointers(createComplexDataFromPointers);
			
		AddressSet resultSet = symEval.flowConstants(flowStart, null, eval, true, monitor);

		return resultSet;
	}

	/**
	 * Check for a global GP register symbol or discovered symbol
	 * @param program
	 * @param set
	 * @param monitor
	 */
	private void checkForGlobalGP(Program program, AddressSetView set, TaskMonitor monitor) {
		Symbol symbol = SymbolUtilities.getLabelOrFunctionSymbol(program, RISCV___GLOBAL_POINTER,
			err => Msg.error(this, err));
		if (symbol != null) {
			gp_assumption_value = symbol.getAddress();
			return;
		}
	}

